create function private.validate_question(q jsonb,k jsonb)returns void language plpgsql immutable set search_path='' as $$declare u jsonb;opt jsonb;ids jsonb;v text;n int;begin
if q->>'id'is null or q->>'type'is null or q->>'max'is null or k->>'questionId'is null or jsonb_typeof(q->'prompt')is distinct from 'string'or length(q->>'prompt')not between 1 and 20000 or (q->>'max')::int not between 1 and 100000 or q->>'id'<>k->>'questionId'then raise exception 'INVALID_QUESTION';end if;perform(q->>'id')::uuid;
if q->>'type'='mcq'then if jsonb_typeof(q->'options')is distinct from 'array'then raise exception 'INVALID_OPTIONS';end if;if jsonb_array_length(q->'options')not between 2 and 6 or(select count(distinct o->>'id')from jsonb_array_elements(q->'options')o)<>jsonb_array_length(q->'options')or not exists(select 1 from jsonb_array_elements(q->'options')o where o->'id'=k->'correct')then raise exception 'INVALID_MCQ';end if;for opt in select value from jsonb_array_elements(q->'options')loop perform(opt->>'id')::uuid;if jsonb_typeof(opt->'text')<>'string'or length(opt->>'text')not between 1 and 4000 then raise exception 'INVALID_OPTION';end if;end loop;
elsif q->>'type'='boolean'then if jsonb_typeof(k->'correct')is distinct from 'boolean'then raise exception 'INVALID_BOOLEAN';end if;
elsif q->>'type'in('blank','match')then if jsonb_typeof(k->'units')is distinct from 'array'or(q->>'type'='blank'and jsonb_typeof(q->'blanks')is distinct from 'array')or(q->>'type'='match'and(jsonb_typeof(q->'left')is distinct from 'array'or jsonb_typeof(q->'right')is distinct from 'array'))then raise exception 'INVALID_UNITS';end if;ids:=case when q->>'type'='blank'then q->'blanks'else(select jsonb_agg(x->'id')from jsonb_array_elements(q->'left')x)end;n:=jsonb_array_length(ids);if n not between 1 and 30 or(select count(distinct x)from jsonb_array_elements_text(ids)x)<>n or jsonb_array_length(k->'units')<>n or(select count(distinct x->>'id')from jsonb_array_elements(k->'units')x)<>n or(select sum((x->>'max')::int)from jsonb_array_elements(k->'units')x)<>(q->>'max')::int then raise exception 'INVALID_UNITS';end if;
for u in select value from jsonb_array_elements(k->'units')loop perform(u->>'id')::uuid;if (u->>'max')::int<=0 or not exists(select 1 from jsonb_array_elements_text(ids)x where x=u->>'id')then raise exception 'INVALID_UNIT';end if;
if q->>'type'='blank'then if jsonb_typeof(u->'alternatives')<>'array'or jsonb_array_length(u->'alternatives')<1 then raise exception 'INVALID_ALTERNATIVES';end if;for v in select jsonb_array_elements_text(u->'alternatives')loop if length(trim(v))=0 then raise exception 'EMPTY_ALTERNATIVE';end if;end loop;elsif not exists(select 1 from jsonb_array_elements(q->'right')x where x->>'id'=u->>'right')then raise exception 'INVALID_PAIR';end if;end loop;
if q->>'type'='match'and(jsonb_array_length(q->'right')<>n or(select count(distinct x->>'right')from jsonb_array_elements(k->'units')x)<>n or(select count(distinct x->>'id')from jsonb_array_elements(q->'right')x)<>n)then raise exception 'INVALID_ONE_TO_ONE_MAP';end if;
elsif q->>'type'='subjective'then if jsonb_typeof(k->'rubric')is distinct from 'array'then raise exception 'INVALID_RUBRIC';end if;if jsonb_array_length(k->'rubric')<1 or(select sum((x->>'max')::int)from jsonb_array_elements(k->'rubric')x)<>(q->>'max')::int or length(coalesce(k->>'reference',''))<1 then raise exception 'INVALID_RUBRIC';end if;for u in select value from jsonb_array_elements(k->'rubric')loop perform(u->>'id')::uuid;if (u->>'max')::int<0 or length(coalesce(u->>'description',''))<1 then raise exception 'INVALID_CRITERION';end if;end loop;
else raise exception 'UNSUPPORTED_TYPE';end if;end$$;
revoke execute on function private.validate_question(jsonb,jsonb)from public,anon,authenticated;
